export const buildings = [
  { id: 1, name: 'Main Campus Building A', floors: 5, rooms: 50, type: 'Academic' },
  { id: 2, name: 'Library Complex', floors: 4, rooms: 30, type: 'Library' },
  { id: 3, name: 'Laboratory Block', floors: 3, rooms: 25, type: 'Laboratory' },
  { id: 4, name: 'Administrative Wing', floors: 2, rooms: 20, type: 'Office' },
  { id: 5, name: 'Student Hostel', floors: 6, rooms: 120, type: 'Residential' },
];

export const sensors = [
  { id: 1, type: 'Temperature', unit: '°C', normalRange: [18, 26], criticalRange: [15, 30] },
  { id: 2, type: 'Humidity', unit: '%', normalRange: [30, 60], criticalRange: [20, 80] },
  { id: 3, type: 'Power Consumption', unit: 'kWh', normalRange: [50, 200], criticalRange: [0, 300] },
  { id: 4, type: 'Air Quality (CO2)', unit: 'ppm', normalRange: [400, 1000], criticalRange: [350, 2000] },
  { id: 5, type: 'Water Flow', unit: 'L/min', normalRange: [10, 50], criticalRange: [0, 100] },
];

export const generateSensorReading = (sensor, isAbnormal = false) => {
  let value;

  if (isAbnormal) {
    // Generate abnormal reading outside normal range
    if (Math.random() > 0.5) {
      value = sensor.criticalRange[1] + Math.random() * 10;
    } else {
      value = sensor.criticalRange[0] - Math.random() * 10;
    }
  } else {
    // Generate normal reading within normal range
    value = sensor.normalRange[0] + Math.random() * (sensor.normalRange[1] - sensor.normalRange[0]);
  }

  return parseFloat(value.toFixed(2));
};

export const getSensorStatus = (value, sensor) => {
  if (value < sensor.criticalRange[0] || value > sensor.criticalRange[1]) {
    return { status: 'Critical', color: 'red', priority: 'High' };
  } else if (value < sensor.normalRange[0] || value > sensor.normalRange[1]) {
    return { status: 'Warning', color: 'orange', priority: 'Medium' };
  }
  return { status: 'Normal', color: 'green', priority: 'Low' };
};

